{
  "contract": "QuantumEnergy",
  "closure": {
    "site_function": "sendFee",
    "site_call": ".balanceOf",
    "functions": [
      "claimReward",
      "getReward",
      "transfer",
      "transferFrom"
    ],
    "justification": "These functions interact with state variables exposed during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "claimReward",
      "getReward",
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "claimReward": 1,
      "getReward": 1,
      "transfer": 1,
      "transferFrom": 1
    }
  },
  "phases": {
    "function": "sendFee",
    "pre": {
      "name": "pre",
      "from_marker": "start_sendFee",
      "to_marker": "before_balanceOf_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_balanceOf_call",
      "to_marker": "after_balanceOf_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_balanceOf_call",
      "to_marker": "end_sendFee"
    },
    "linearization_point": "after_balanceOf_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount in transfer during the callback window",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "feeQueue + LiqQueue == balanceOf[address(this)] + inFlight",
    "stable_formula": "feeQueue + LiqQueue == balanceOf[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "feeQueue + LiqQueue <= balanceOf[address(this)]",
    "rule": "The exposure invariant ensures that the sum of feeQueue and LiqQueue is conserved across the callback window, accounting for in-flight transfers."
  }
}
